        boolean isWeightActivated = ((CheckBox)dialog.findViewById(R.id.WeightCheckBox)).isChecked();
        Double weight = 0.0;
        if(isWeightActivated)
            weight = Double.valueOf(((TextView)dialog.findViewById(R.id.WeightEdit)).getText().toString());

